    "book_type": "textbook",
    "year": 2026,
    "description": "বাংলা:\nজাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) কর্তৃক প্রকাশিত নবম ও দশম শ্রেণির \"বাংলা ভাষার ব্যাকরণ ও নির্মিতি\" পাঠ্যবই। এই বইটিতে বাংলা ভাষার সঠিক ব্যাকরণগত নিয়ম, ধ্বনিতত্ত্ব, রূপতত্ত্ব, বাক্যতত্ত্ব এবং বিভিন্ন ধরনের নির্মিতি (যেমন: প্রবন্ধ, দরখাস্ত, ভাবসম্প্রসারণ ইত্যাদি) সহজ ও সুন্দরভাবে তুলে ধরা হয়েছে। মাধ্যমিক স্তরের শিক্ষার্থীদের বাংলা ভাষার দক্ষতা ও দক্ষতা বৃদ্ধিতে বইটি অত্যন্ত সহায়ক।\n\nEnglish:\n\"Bangla Bhashar Byakoron O Nirmiti\" is the official National Curriculum and Textbook Board (NCTB) textbook designed for Class 9 and 10 students in Bangladesh. This book offers a comprehensive guide to Bengali grammar rules, phonetics, morphology, syntax, and writing skills (such as essays, letters, and compositions). It is an essential educational resource for mastering the Bengali language at the secondary school level.",
