    "id": "b-910-42",
    "title": "গার্হস্থ্যবিজ্ঞান – নবম ও দশম শ্রেণি (NCTB) / Home Science – Class 9 & 10 (NCTB Textbook)",
    "slug": "home-science-class-9-10-nctb-textbook",
