    "book_type": "textbook",
    "year": 2026,
    "description": "বাংলা বিবরণ:\nজাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) কর্তৃক প্রণীত নবম ও দশম শ্রেণির গার্হস্থ্যবিজ্ঞান (Home Science) পাঠ্যবই। এই বইটিতে গৃহ ব্যবস্থাপনা, সম্পদের ব্যবহার, শিশু বিকাশ ও পারিবারিক সম্পর্ক, বস্ত্র ও পোশাক শিল্প এবং পুষ্টি ও খাদ্য পরিকল্পনার মতো গুরুত্বপূর্ণ বিষয়াবলি বিস্তারিত ও সহজ ভাষায় আলোচনা করা হয়েছে। এসএসসি (SSC) পরীক্ষার্থীদের জন্য এটি একটি প্রয়োজনীয় বোর্ড বই।\n\nEnglish Description:\nThe official Home Science textbook for Class 9 and 10 students, published by the National Curriculum and Textbook Board (NCTB), Bangladesh. This comprehensive textbook covers essential topics including Home Management, Resource Utilization, Child Development & Family Relations, Textiles & Clothing, and Food & Nutrition. It is an indispensable study guide for SSC candidates and secondary level students following the NCTB curriculum.",
