    "description": "নবম ও দশম শ্রেণির শিক্ষার্থীদের জন্য জাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) কর্তৃক প্রণীত পরিমার্জিত পাঠ্যবই ‘বাংলা সাহিত্য’। এই বইটিতে নবম-দশম শ্রেণির পাঠ্যক্রম অনুযায়ী নির্বাচিত গুরুত্বপূর্ণ কবিতা, গল্প, প্রবন্ধ ও নাটক অন্তর্ভুক্ত রয়েছে। মাধ্যমিক (SSC) পরীক্ষার্থীদের বাংলা প্রথম পত্রের প্রস্তুতি সহজ ও সহজবোধ্য করতে বইটি বিশেষভাবে সাজানো হয়েছে।\n\nBangla Sahitya for Class 9 and 10 is the official textbook published by the National Curriculum and Textbook Board (NCTB), Bangladesh. Revised for the latest academic curriculum, this book features a curated collection of classic and contemporary Bengali poems, prose, essays, and dramas designed to enhance students' literary comprehension and language skills for the SSC examination.",
