    "year": 2026,
    "description": "বাংলা :\n\nজাতীয় শিক্ষাক্রম ও পাঠ্যপুস্তক বোর্ড (NCTB) কর্তৃক অনুমোদিত নবম ও দশম শ্রেণির শিক্ষার্থীদের জন্য 'অর্থনীতি' পাঠ্যবই। বইটি মাধ্যমিক স্তরের শিক্ষার্থীদের অর্থনীতির মৌলিক নীতি, উৎপাদন, চাহিদা, জোগান এবং বাংলাদেশের অর্থনীতির নানা বিষয় সহজ ও প্রাঞ্জল ভাষায় শেখার জন্য রচিত। পরীক্ষায় ভালো ফলাফলের পাশাপাশি অর্থনীতি সম্পর্কে পরিষ্কার ধারণা পেতে বইটি অত্যন্ত প্রয়োজনীয়।\n\nEnglish :\n\nThe official 'Economics' textbook for Class 9 and 10 students, approved by the National Curriculum and Textbook Board (NCTB). This book introduces secondary level students to the fundamental concepts of economics, including supply and demand, production, and the economic framework of Bangladesh in a simple and comprehensive manner. An essential textbook for secondary curriculum preparation and building foundational knowledge in economics.",
