export async function getBooks(): Promise<Book[]> {
  const map = new Map<string, Book>();
  MOCK_BOOKS.filter(b => b.is_published).forEach(b => map.set(b.slug || b.id, b));
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .eq('is_published', true)
      .order('id', { ascending: true });
    if (!error && data) {
      data.forEach(b => map.set(b.slug || b.id, b as Book));
    }
  }
  return Array.from(map.values());
}

export async function getBookBySlug(slug: string): Promise<Book | null> {
  const foundMock = MOCK_BOOKS.find(b => b.slug === slug);
  if (foundMock) return foundMock;
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .eq('slug', slug)
      .single();
    if (!error && data) return data as Book;
  }
  return null;
}

export async function getBooksByClass(classSlug: string): Promise<Book[]> {
  const map = new Map<string, Book>();
  MOCK_BOOKS.filter(b => b.class_slug === classSlug && b.is_published).forEach(b => map.set(b.slug || b.id, b));
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .eq('class_slug', classSlug)
      .eq('is_published', true)
      .order('id', { ascending: true });
    if (!error && data) {
      data.forEach(b => map.set(b.slug || b.id, b as Book));
    }
  }
  return Array.from(map.values());
}

export async function getBooksBySubject(classSlug: string, subjectSlug: string): Promise<Book[]> {
  const map = new Map<string, Book>();
  MOCK_BOOKS.filter(
    b => b.class_slug === classSlug && b.subject_slug === subjectSlug && b.is_published
  ).forEach(b => map.set(b.slug || b.id, b));
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .eq('class_slug', classSlug)
      .eq('subject_slug', subjectSlug)
      .eq('is_published', true)
      .order('id', { ascending: true });
    if (!error && data) {
      data.forEach(b => map.set(b.slug || b.id, b as Book));
    }
  }
  return Array.from(map.values());
}

export async function getLatestBooks(limit = 24): Promise<Book[]> {
  const allBooks = await getBooks();
  const booksCopy = [...allBooks];
  booksCopy.sort((a, b) => {
    if (a.is_latest && !b.is_latest) return -1;
    if (!a.is_latest && b.is_latest) return 1;
    return new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime();
  });
  return booksCopy.slice(0, limit);
}

export async function getBooksByType(bookType: 'textbook' | 'guide' | 'solution'): Promise<Book[]> {
  const map = new Map<string, Book>();
  MOCK_BOOKS.filter(b => (b.book_type === bookType || (bookType === 'guide' && b.book_type === 'solution')) && b.is_published).forEach(b => map.set(b.slug || b.id, b));
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .eq('book_type', bookType)
      .eq('is_published', true)
      .order('id', { ascending: true });
    if (!error && data) {
      data.forEach(b => map.set(b.slug || b.id, b as Book));
    }
  }
  return Array.from(map.values());
}

export async function searchBooks(query: string): Promise<Book[]> {
  if (!query || query.trim() === '') return [];
  const q = query.toLowerCase().trim();
  
  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .select('*')
      .or(`title.ilike.%${q}%,subject.ilike.%${q}%,class_name.ilike.%${q}%,description.ilike.%${q}%`)
      .eq('is_published', true);
    if (!error && data && data.length > 0) return data as Book[];
  }

  return MOCK_BOOKS.filter(b => {
    return (
      b.is_published &&
      (b.title.toLowerCase().includes(q) ||
        b.subject.toLowerCase().includes(q) ||
        b.class_name.toLowerCase().includes(q) ||
        b.description.toLowerCase().includes(q))
    );
  });
}

export async function getRelatedBooks(currentBook: Book, limit = 6): Promise<Book[]> {
  const sameClassBooks = await getBooksByClass(currentBook.class_slug);
  let related = sameClassBooks.filter(b => b.id !== currentBook.id && b.slug !== currentBook.slug);

  if (related.length < limit) {
    const allBooks = await getBooks();
    const additional = allBooks.filter(
      b => b.id !== currentBook.id && b.slug !== currentBook.slug && !related.some(r => r.id === b.id)
    );
    related = [...related, ...additional];
  }

  return related.slice(0, limit);
}

// Helper functions for Admin insertion, updating, and deletion
export async function createBook(bookData: Omit<Book, 'id' | 'created_at' | 'updated_at'>): Promise<Book> {
  const newBook: Book = {
    ...bookData,
    id: 'b-' + Date.now(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .insert([bookData])
      .select()
      .single();
    if (!error && data) return data as Book;
  }

  MOCK_BOOKS.unshift(newBook);
  return newBook;
}

export async function updateBook(originalSlug: string, bookData: Partial<Book>): Promise<Book | null> {
  const updatedData = {
    ...bookData,
    updated_at: new Date().toISOString(),
  };

  if (supabase) {
    const { data, error } = await supabase
      .from('books')
      .update(updatedData)
      .eq('slug', originalSlug)
      .select()
      .single();
    if (!error && data) return data as Book;
  }

  const index = MOCK_BOOKS.findIndex(b => b.slug === originalSlug);
  if (index !== -1) {
    MOCK_BOOKS[index] = {
      ...MOCK_BOOKS[index],
      ...updatedData,
    };
    return MOCK_BOOKS[index];
  }
  return null;
}

export async function deleteBook(slug: string): Promise<boolean> {
  if (supabase) {
    const { error } = await supabase
      .from('books')
      .delete()
      .eq('slug', slug);
    if (!error) return true;
  }

  MOCK_BOOKS = MOCK_BOOKS.filter(b => b.slug !== slug);
  return true;
}
